fn flip_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
     .map(|c| {
         if c.is_ascii_lowercase() {
             c.to_ascii_uppercase()
         } else if c.is_ascii_uppercase() {
             c.to_ascii_lowercase()
         } else {
             c
         }
     })
     .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let input: Vec<char> = vec![];
        let output = flip_case(input.clone());
        assert_eq!(output, input);
    }

    #[test]
    fn test_all_lowercase() {
        let input: Vec<char> = "abcdefxyz".chars().collect();
        let output = flip_case(input);
        assert_eq!(output, "ABCDEFXYZ".chars().collect::<Vec<_>>());
    }

    #[test]
    fn test_all_uppercase() {
        let input: Vec<char> = "HELLOWORLD".chars().collect();
        let output = flip_case(input);
        assert_eq!(output, "helloworld".chars().collect::<Vec<_>>());
    }

    #[test]
    fn test_mixed() {
        let input: Vec<char> = "RustLang123!?".chars().collect();
        let output = flip_case(input);
        assert_eq!(
            output,
            "rUSTlANG123!?".chars().collect::<Vec<_>>()
        );
    }

    #[test]
    fn test_unicode_unchanged() {
        let input: Vec<char> = "ñÑçÇ日A".chars().collect();
        let output = flip_case(input);
        // Only ASCII 'A' flips to 'a'. Others remain the same.
        assert_eq!(
            output,
            vec!['ñ', 'Ñ', 'ç', 'Ç', '日', 'a']
        );
    }
}